import json,pathlib,subprocess,os
root=pathlib.Path('/home/user/.actc_gui_ready_vm_001')
r={'files':{},'processes':[]}
for name in ('entered.json','stdout.txt','gui_ready.json'):
 p=root/name
 if p.exists():r['files'][name]=p.read_text()[:2500]
for p in pathlib.Path('/proc').iterdir():
 if not p.name.isdigit():continue
 try:
  comm=(p/'comm').read_text().strip()
  if comm=='FreeCAD':r['processes'].append({'pid':p.name,'cmdline':(p/'cmdline').read_text(errors='replace'),'state':(p/'status').read_text().splitlines()[:3]})
 except (FileNotFoundError,PermissionError):pass
env=dict(os.environ,DISPLAY=':0',XAUTHORITY='/run/user/1000/gdm/Xauthority')
w=subprocess.run(['wmctrl','-lpG'],env=env,capture_output=True,text=True,timeout=10)
r['windows']=w.stdout; r['windows_error']=w.stderr
print(json.dumps(r))
